import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static long computePower(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    static class UnionFindSet {
        int[] parent;
        int[] rank;
        int components;

        public UnionFindSet(int n) {
            parent = new int[n];
            rank = new int[n];
            components = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int u) {
            if (parent[u] != u) {
                parent[u] = find(parent[u]);
            }
            return parent[u];
        }

        void unite(int u, int v) {
            u = find(u);
            v = find(v);
            if (u != v) {
                if (rank[u] < rank[v]) {
                    int temp = u;
                    u = v;
                    v = temp;
                }
                parent[v] = u;
                if (rank[u] == rank[v]) {
                    rank[u]++;
                }
                components--;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        boolean[] visited = new boolean[(int)p];
        UnionFindSet uf = new UnionFindSet((int)p);

        for (long i = 0; i < p; i++) {
            for (long j = i; !visited[(int)j]; j = (j * k) % p) {
                visited[(int)j] = true;
                uf.unite((int)i, (int)j);
            }
        }

        int c = uf.components;
        if (k != 1) c--;
        System.out.println(computePower(p, c));
        sc.close();
    }
}
